## ✅ **GRAPH IN C — Create, BFS & DFS (Adjacency Matrix)**

```c
#include <stdio.h>

#define MAX 10

int graph[MAX][MAX], visited[MAX];
int n;

void createGraph() {
    int i, j;
    printf("Enter number of vertices: ");
    scanf("%d", &n);

    printf("Enter adjacency matrix:\n");
    for(i = 0; i < n; i++)
        for(j = 0; j < n; j++)
            scanf("%d", &graph[i][j]);
}

void DFS(int v) {
    int i;
    visited[v] = 1;
    printf("%d ", v);
    for(i = 0; i < n; i++)
        if(graph[v][i] == 1 && !visited[i])
            DFS(i);
}

void BFS(int v) {
    int queue[MAX], front = 0, rear = 0;
    int i;

    visited[v] = 1;
    queue[rear++] = v;

    while(front != rear) {
        v = queue[front++];
        printf("%d ", v);

        for(i = 0; i < n; i++) {
            if(graph[v][i] == 1 && !visited[i]) {
                visited[i] = 1;
                queue[rear++] = i;
            }
        }
    }
}

int main() {
    int start;

    createGraph();
    printf("Enter start vertex: ");
    scanf("%d", &start);

    printf("\nDFS: ");
    for(int i = 0; i < n; i++) visited[i] = 0;
    DFS(start);

    printf("\nBFS: ");
    for(int i = 0; i < n; i++) visited[i] = 0;
    BFS(start);

    return 0;
}
```

