## ✅ Graph Using Adjacency List in C (Exam-Ready)

```c
#include <stdio.h>
#include <stdlib.h>

#define MAX 10

struct Node {
    int vertex;
    struct Node* next;
};

struct Node* graph[MAX];
int visited[MAX];
int n;

struct Node* createNode(int v) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->vertex = v;
    newNode->next = NULL;
    return newNode;
}

void addEdge(int src, int dest) {
    struct Node* newNode = createNode(dest);
    newNode->next = graph[src];
    graph[src] = newNode;
}

void createGraph() {
    int edges, u, v;
    printf("Enter number of vertices: ");
    scanf("%d", &n);

    for(int i = 0; i < n; i++)
        graph[i] = NULL;

    printf("Enter number of edges: ");
    scanf("%d", &edges);

    printf("Enter edges (u v):\n");
    for(int i = 0; i < edges; i++) {
        scanf("%d %d", &u, &v);
        addEdge(u, v);
        addEdge(v, u); // Undirected
    }
}

void displayGraph() {
    for(int i = 0; i < n; i++) {
        struct Node* temp = graph[i];
        printf("%d → ", i);
        while(temp) {
            printf("%d ", temp->vertex);
            temp = temp->next;
        }
        printf("\n");
    }
}

void DFS(int v) {
    visited[v] = 1;
    printf("%d ", v);

    struct Node* temp = graph[v];
    while(temp) {
        int u = temp->vertex;
        if(!visited[u])
            DFS(u);
        temp = temp->next;
    }
}

void BFS(int start) {
    int queue[MAX], front = 0, rear = 0;
    visited[start] = 1;
    queue[rear++] = start;

    while(front != rear) {
        int v = queue[front++];
        printf("%d ", v);

        struct Node* temp = graph[v];
        while(temp) {
            int u = temp->vertex;
            if(!visited[u]) {
                visited[u] = 1;
                queue[rear++] = u;
            }
            temp = temp->next;
        }
    }
}

int main() {
    int start;
    createGraph();
    displayGraph();

    printf("Enter starting vertex: ");
    scanf("%d", &start);

    printf("DFS: ");
    for(int i = 0; i < n; i++) visited[i] = 0;
    DFS(start);

    printf("\nBFS: ");
    for(int i = 0; i < n; i++) visited[i] = 0;
    BFS(start);

    return 0;
}
```

