## ✅ C++ Code — Adjacency List (Create + Display)

This matches the style shown in your screenshots.

```cpp
#include <iostream>
using namespace std;

#define MAX 10

class GraphNode {
public:
    int vertex;
    GraphNode* next;

    GraphNode(int v) {
        vertex = v;
        next = NULL;
    }
};

class ListGraph {
    GraphNode* list[MAX];
    int n; // number of vertices

public:
    ListGraph(int nov) {
        n = nov;
        for(int i = 0; i < n; i++)
            list[i] = NULL;
    }

    void create();
    void display();
};

void ListGraph::create() {
    int i, j;
    char ans;

    for(i = 0; i < n; i++) {
        for(j = 0; j < n; j++) {
            cout << "Is there an edge between vertex " << i
                 << " and " << j << "? (y/n): ";
            cin >> ans;

            if(ans == 'y' || ans == 'Y') {
                GraphNode* newNode = new GraphNode(j);

                if(list[i] == NULL)
                    list[i] = newNode;
                else {
                    GraphNode* temp = list[i];
                    while(temp->next != NULL)
                        temp = temp->next;
                    temp->next = newNode;
                }
            }
        }
    }
}

void ListGraph::display() {
    for(int i = 0; i < n; i++) {
        cout << "V" << i << " -> ";
        GraphNode* temp = list[i];
        while(temp != NULL) {
            cout << "V" << temp->vertex << " -> ";
            temp = temp->next;
        }
        cout << "NULL\n";
    }
}

int main() {
    int vertices;
    cout << "Enter number of vertices: ";
    cin >> vertices;

    ListGraph g(vertices);
    g.create();
    g.display();

    return 0;
}
```

